<?php
declare(strict_types=1);
if (!defined('ZODEE_INTERNAL') && PHP_SAPI !== 'cli') { http_response_code(404); exit; }
function community_form(string $action,string $label,string $username,string $csrf,array $extra=[]): void { ?>
<form method="post" action="/account/contact" class="inline-form"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="<?=e($action)?>"><input type="hidden" name="username" value="<?=e($username)?>"><?php foreach($extra as $key=>$value):?><input type="hidden" name="<?=e($key)?>" value="<?=e($value)?>"><?php endforeach?><button class="button button-small"><?=e($label)?></button></form><?php }
function community_page(ZodService $service,string $csrf): void {
    $me=$service->currentAccount();?><section class="shell section page-section"><?php title_block('PLAY TOGETHER','Your community.','Opt-in friend requests and invitations. Presence means activity on this portal within the last three minutes, shared only with accepted friends. Blocking stops contact; it does not exclude people from the same public server.');
    if(!$me){?><a class="button" href="/account">Sign in to manage friends</a></section><?php return;}
    foreach(['message','error'] as $notice)if(is_string($_GET[$notice]??null))echo '<p class="notice" role="status">'.e(substr($_GET[$notice],0,180)).'</p>';
    $data=$service->community();?><div class="info-grid"><section class="panel panel-pad"><h2>Friends & requests</h2><form action="/account/contact" method="post" class="account-form"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="request"><label for="friend-name">Commander username</label><input id="friend-name" name="username" maxlength="24" required><button class="button">Send request</button></form><p class="small">Requests are disabled by default. Enable them in <a href="/account#privacy">account privacy</a>.</p>
    <?php foreach($data['friends'] as $friend):?><article class="community-row"><h3><?=e($friend['username'])?></h3><p><?=e($friend['status']==='friend'?($friend['online']?'Active on portal':'Offline / presence hidden'):$friend['status'].' request')?></p><div class="button-row"><?php if($friend['status']==='incoming')community_form('accept','Accept',$friend['username'],$csrf);community_form('remove',$friend['status']==='friend'?'Remove friend':'Decline / cancel',$friend['username'],$csrf);community_form('block','Block',$friend['username'],$csrf);?></div>
    <?php if($friend['status']==='friend'):?><form method="post" action="/account/contact" class="account-form"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="invite"><input type="hidden" name="username" value="<?=e($friend['username'])?>"><label>Invite to a public server<select name="server" required><?php foreach($service->servers() as $server):?><option value="<?=e($server['id'])?>"><?=e($server['name'])?></option><?php endforeach?></select></label><button class="button button-small">Send 15-minute invitation</button></form><?php endif?></article><?php endforeach?>
    <?php if(!$data['friends']):?><p>No friends or requests yet.</p><?php endif?></section><section class="panel panel-pad"><h2>Invitations</h2><?php foreach($data['invitations'] as $invite):?><article class="community-row"><p><strong><?=e($invite['username'])?></strong> invited you to <?=e($invite['server_id'])?>.</p><a class="button" href="/servers?server=<?=e($invite['server_id'])?>">View server & get your own ticket</a><?php community_form('dismiss','Dismiss','',$csrf,['invitation'=>$invite['id']]);?></article><?php endforeach?><?php if(!$data['invitations']):?><p>No active invitations. Invitations never contain a friend's ticket.</p><?php endif?><h2>Blocked commanders</h2><?php foreach($data['blocked'] as $blocked):?><p><?=e($blocked['username'])?></p><?php community_form('unblock','Unblock',$blocked['username'],$csrf);endforeach?>
    <form method="post" action="/account/contact" class="account-form"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="block"><label>Block by username<input name="username" required maxlength="24"></label><button class="button">Block contact</button></form></section></div></section><?php
}
function account_tools(ZodService $service,string $csrf): void {
    $me=$service->currentAccount();?><section class="shell section"><?php if(!$me){?><section class="panel panel-pad"><h2>Recover your account</h2><p>Use one of the backup codes you previously saved. No email delivery is required.</p><form method="post" action="/account/recover" class="account-form"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><label>Username<input name="username" required maxlength="24" autocomplete="username"></label><label>One-use recovery code<input name="code" required maxlength="64" autocomplete="off"></label><label>New password<input type="password" name="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><button class="button">Reset password</button></form></section></section><?php return;}
    $prefs=$service->preferences();?><div class="info-grid section"><section class="panel panel-pad" id="privacy"><h2>Privacy & friends</h2><form method="post" action="/account/privacy" class="account-form"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><label>Profile visibility<select name="visibility"><?php foreach(['public','friends','private'] as $value):?><option <?=$prefs['visibility']===$value?'selected':''?> value="<?=$value?>"><?=ucfirst($value)?></option><?php endforeach?></select></label><label><input type="checkbox" name="allow_requests" <?=$prefs['allow_requests']?'checked':''?>> Accept friend requests</label><label><input type="checkbox" name="show_online" <?=$prefs['show_online']?'checked':''?>> Share recent portal activity with friends</label><button class="button">Save privacy</button></form><p>Private/friends-only profiles are omitted from public leaderboards and winner names. Public games require an account; private/LAN games do not.</p><a href="/community">Manage friends and invitations</a></section>
    <section class="panel panel-pad"><h2>Recovery codes</h2><p>Generate eight one-use backup codes and store them offline. A new set replaces the old one. Recovery signs out all website sessions.</p><form action="/account/recovery-codes" method="post" class="account-form"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><label>Current password<input type="password" name="password" required maxlength="128" autocomplete="current-password"></label><button class="button">Generate recovery codes</button></form></section></div>
    <section class="panel panel-pad"><h2>Active sessions</h2><p>Sessions last up to one day. Revoke a session you no longer use.</p><?php foreach($service->sessions() as $session):?><form action="/account/sessions" method="post" class="community-row"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="<?=e($session['id'])?>"><span><?=e($session['current']?'This session':'Other session')?> · expires <?=e($session['expires_at'])?> UTC</span> <button class="button button-small">Sign out</button></form><?php endforeach?><form action="/account/sessions" method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="others"><button class="button">Sign out all other sessions</button></form></section></section><?php
}
function creations_page(ZodService $service,string $csrf): void {
    ?><section class="shell section page-section"><?php title_block('COMMUNITY CREATIONS','New battlefields. New stories.','Browse screenshots, required engine versions and release history. Download a map or campaign pack, then use the editor’s Open or campaign import preview before installing.');
    $id=is_string($_GET['version']??null)?$_GET['version']:'';
    if($id!==''){$v=$service->creationVersion($id);$preview=json_decode($v['manifest'],true,512,JSON_THROW_ON_ERROR);?><article class="panel panel-pad"><span class="eyebrow"><?=e($v['kind'])?> · <?=e($v['approved']?'Published':'Pending moderator approval')?></span><h2><?=e($v['title'])?> — <?=e($v['version'])?></h2><p>By <?=e($v['username'])?> · requires engine <?=e($v['engine_min'])?> or newer</p><img class="creation-preview" src="<?=e(route_url('/creations/image/'.$id))?>" alt="Author screenshot of <?=e($v['title'])?>"><p><?=e($v['description'])?></p><p><?=e($v['notes'])?></p><details><summary>Preview package contents & compatibility</summary><?php if(!empty($preview['engine_max'])):?><p>Maximum engine version: <?=e($preview['engine_max'])?></p><?php endif?><?php if(!empty($preview['requires'])):?><p>Required packs: <?=e(implode(', ',$preview['requires']))?></p><?php endif?><p><?=e($preview['note'])?></p><ul><?php foreach($preview['files'] as $file):?><li><?=e($file)?></li><?php endforeach?></ul></details><p><a class="text-link" href="/reports?kind=creation&amp;target=<?=e($id)?>">Report this revision</a></p><p class="small mono">SHA-256: <?=e($v['sha256'])?></p><a class="button" href="/creations/download/<?=e($id)?>">Download <?=e($v['filename'])?></a><p class="small">Project ID for future versions: <?=e($v['id'])?></p><h3>Version history</h3><?php foreach($service->creationHistory($v['id']) as $previous):?><p><a href="/creations?version=<?=e($previous['id'])?>"><?=e($previous['version'])?></a> · <?=e($previous['created_at'])?> UTC — <?=e($previous['notes'])?></p><?php endforeach?></article><?php }
    $rows=$service->creations();?><form class="search-form" role="search"><label>Search creations<input type="search" name="q" value="<?=e(is_string($_GET['q']??null)?$_GET['q']:'')?>" maxlength="80"></label><button class="button">Search</button></form><div class="enhancement-grid"><?php $shown=[];foreach($rows as $row){if(isset($shown[$row['id']]))continue;$q=is_string($_GET['q']??null)?$_GET['q']:'';if($q!==''&&stripos($row['title'].' '.$row['description'].' '.$row['username'],$q)===false)continue;$shown[$row['id']]=true;?><article class="feature-card"><img loading="lazy" class="creation-preview" src="<?=e(route_url('/creations/image/'.$row['revision']))?>" alt="<?=e($row['title'])?> screenshot"><span class="eyebrow"><?=e($row['kind'])?> · <?=e($row['version'])?><?=$row['approved']?'':' · pending review'?></span><h3><?=e($row['title'])?></h3><p><?=e($row['description'])?></p><p>By <?=e($row['username'])?> · engine <?=e($row['engine_min'])?>+</p><a class="button" href="/creations?version=<?=e($row['revision'])?>">Preview & version history</a></article><?php }?></div><?php if(!$shown):?><p>No matching published creations yet.</p><?php endif?>
    <?php if($service->currentAccount()):?><details class="panel panel-pad section"><summary>Share a creation or publish a new version</summary><p>Share only your own work or files you have permission to redistribute. Original game media must not be uploaded. Submissions need moderator approval before appearing publicly.</p><form action="/creations/submit" method="post" enctype="multipart/form-data" class="account-form"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><?php foreach(['project'=>'Existing project ID (blank for new)','title'=>'Title','description'=>'Description','version'=>'Version (e.g. 1.0.0)','engine_min'=>'Minimum engine version (e.g. 0.7.0)','notes'=>'Version notes'] as $name=>$label):?><label><?=e($label)?><input name="<?=$name?>" <?=$name==='project'||$name==='notes'?'':'required'?> maxlength="<?=$name==='description'?2000:($name==='notes'?1000:($name==='project'?64:80))?>"></label><?php endforeach?><label>Map (.map) or campaign (.zip), up to 8 MiB<input name="creation" type="file" accept=".map,.zip" required></label><label>Screenshot (PNG/JPEG, up to 2 MiB and 2048 × 2048)<input name="screenshot" type="file" accept="image/png,image/jpeg" required></label><label><input name="rights" type="checkbox" value="yes" required> I have permission to redistribute every included file and screenshot.</label><button class="button">Submit for review & preview</button></form></details><?php else:?><a href="/account">Sign in to share your creations</a><?php endif?></section><?php
}
